function normalize(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/[^a-z]/g, "")
    .slice(0, WORD_LENGTH);
}

function displayWord(word) {
  return word.toUpperCase();
}

function displayWords(words) {
  return words.map(displayWord).join(", ");
}

function loadUsedWords() {
  try {
    const words = JSON.parse(localStorage.getItem(USED_WORDS_KEY) || "[]");
    return Array.isArray(words) ? words.filter((word) => isKnownWord(word)) : [];
  } catch {
    return [];
  }
}

function rememberUsedWords(words) {
  const limit = Math.max(1, WORDS.length);
  const seen = new Set();
  const merged = [...words, ...loadUsedWords()].filter((word) => {
    if (!isKnownWord(word) || seen.has(word)) return false;
    seen.add(word);
    return true;
  });
  localStorage.setItem(USED_WORDS_KEY, JSON.stringify(merged.slice(0, limit)));
}

function normalizeWordDeck(deck) {
  const seen = new Set();
  return (Array.isArray(deck) ? deck : []).filter((word) => {
    if (!isKnownWord(word) || seen.has(word)) return false;
    seen.add(word);
    return true;
  });
}

function loadWordDeck() {
  try {
    const parsed = JSON.parse(localStorage.getItem(WORD_DECK_KEY) || "[]");
    return normalizeWordDeck(parsed);
  } catch {
    return [];
  }
}

function saveWordDeck(deck) {
  localStorage.setItem(WORD_DECK_KEY, JSON.stringify(normalizeWordDeck(deck)));
}

function freshWordDeck(exclude = []) {
  const excluded = new Set(exclude.filter((word) => isKnownWord(word)));
  const preferred = WORDS.filter((word) => !excluded.has(word));
  const delayed = WORDS.filter((word) => excluded.has(word));
  return [...shuffledCopy(preferred), ...shuffledCopy(delayed)];
}

function takeWordsFromDeck(count) {
  const wanted = Math.min(Math.max(1, count), WORDS.length);
  let deck = loadWordDeck();
  const chosen = [];
  while (chosen.length < wanted) {
    if (!deck.length) {
      deck = freshWordDeck([...loadUsedWords(), ...chosen]);
    }
    const next = deck.shift();
    if (isKnownWord(next) && !chosen.includes(next)) {
      chosen.push(next);
    }
  }
  saveWordDeck(deck);
  rememberUsedWords(chosen);
  return chosen;
}

function todayId() {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function fridayOverride() {
  const value = new URLSearchParams(window.location.search).get("friday");
  if (value === "1" || value === "true" || value === "gold") return true;
  if (value === "0" || value === "false") return false;
  return null;
}

function isPetkoFriday() {
  const override = fridayOverride();
  return override === null ? new Date().getDay() === 5 : override;
}

function weekendWitchOverride() {
  const value = new URLSearchParams(window.location.search).get("witch");
  if (value === "1" || value === "true" || value === "preview") return true;
  if (value === "0" || value === "false") return false;
  return null;
}

function isWeekendWitchActive(date = new Date()) {
  const override = weekendWitchOverride();
  if (override !== null) return override;
  const localPreview = window.location.protocol === "file:" ||
    window.location.hostname === "localhost" ||
    window.location.hostname === "127.0.0.1";
  if (localPreview) return true;
  const day = date.getDay();
  return day === 0 || day === 6;
}

function weekendWitchId(date = new Date()) {
  const saturday = new Date(date);
  if (saturday.getDay() === 0) saturday.setDate(saturday.getDate() - 1);
  const year = saturday.getFullYear();
  const month = String(saturday.getMonth() + 1).padStart(2, "0");
  const day = String(saturday.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function isWeekendWitchAvatarId(id = "") {
  return WEEKEND_WITCH_AVATAR_IDS.includes(String(id || "").trim());
}

function isWeekendHunterAvatarId(id = "") {
  const clean = String(id || "").trim();
  if (!clean) return false;
  if (clean === "male-50" || clean.toUpperCase() === "M50") return true;
  return challengeAvatarCode(profileAvatarById(clean)) === "M50";
}

function isWeekendEventAvatarId(id = "") {
  return isWeekendWitchAvatarId(id) || isWeekendHunterAvatarId(id);
}

function currentYearId() {
  return todayId().slice(0, 4);
}

function loadResults() {
  try {
    return JSON.parse(localStorage.getItem(RESULT_STORAGE_KEY) || "[]");
  } catch {
    return [];
  }
}

function saveResults(results) {
  localStorage.setItem(RESULT_STORAGE_KEY, JSON.stringify(results.slice(0, 30)));
}

function emptyFridayBonus() {
  return { year: currentYearId(), normalStreak: 0, normalBonus: 0, competitive: {} };
}

function loadFridayBonus() {
  try {
    const data = { ...emptyFridayBonus(), ...JSON.parse(localStorage.getItem(FRIDAY_BONUS_KEY) || "{}") };
    if (data.year !== currentYearId()) return emptyFridayBonus();
    data.competitive = data.competitive && typeof data.competitive === "object" ? data.competitive : {};
    return data;
  } catch {
    return emptyFridayBonus();
  }
}

function saveFridayBonus(data) {
  localStorage.setItem(FRIDAY_BONUS_KEY, JSON.stringify({ ...data, year: currentYearId() }));
}

function fridayBonusTotal(data = loadFridayBonus()) {
  const competitiveBonus = Object.values(data.competitive || {}).reduce((sum, value) => sum + (Number(value) || 0), 0);
  return (Number(data.normalBonus) || 0) + competitiveBonus;
}

function updateFridayTheme() {
  const friday = isPetkoFriday();
  document.body.dataset.friday = friday ? "true" : "false";
  if (petkoSplashImage) {
    petkoSplashImage.src = friday ? "petak-splash.png" : "petko-splash.png";
    petkoSplashImage.alt = friday ? "Petko Friday" : "Petko";
  }
  if (statusLogoEl) {
    statusLogoEl.src = friday ? "petak-za-petka-logo.png" : "logo-cut.png";
    statusLogoEl.alt = friday ? "Petko Friday" : "G-Lab";
  }
}

