let petkoMoodTimer = null;
let petkoMoodLastShownAt = 0;
let petkoMoodQuietGuesses = 0;
const petkoMomentBags = {};
const petkoImageBags = {};

function shuffledCopy(items) {
  const copy = [...items];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[swapIndex]] = [copy[swapIndex], copy[index]];
  }
  return copy;
}

function takeFromBag(store, key, items) {
  if (!Array.isArray(items)) return items;
  if (!store[key] || !store[key].length) {
    store[key] = shuffledCopy(items);
  }
  return store[key].shift();
}

function pickPetkoMoment(name) {
  const options = PETKO_MOMENTS[name] || PETKO_MOMENTS.start;
  return takeFromBag(petkoMomentBags, name, options);
}

function playPetkoMoment(name, options = {}) {
  const moment = pickPetkoMoment(name);
  showPetkoMood(moment.mood, options.text || moment.text, PETKO_MOOD_DURATION, {
    minGap: options.minGap,
    force: options.force
  });
}

function showPetkoMood(mood = "hello", text = "Hello!", duration = 1800, options = {}) {
  if (!petkoMood || !petkoMoodImage || !petkoMoodText) return;
  const visibleDuration = Math.max(duration, PETKO_MOOD_DURATION);
  const now = Date.now();
  if (!options.force && now - petkoMoodLastShownAt < (options.minGap || 5500)) return;
  petkoMoodLastShownAt = now;
  const moodImages = PETKO_MOODS[mood] || PETKO_MOODS.hello;
  const src = takeFromBag(petkoImageBags, mood, moodImages);
  const sideShift = options.sideShift ?? [-18, -8, 0, 10, 20][Math.floor(Math.random() * 5)];
  petkoMood.style.setProperty("--pwq-side-shift", `${sideShift}px`);
  const centerShift = options.centerShift ?? [-42, -22, 0, 24, 44][Math.floor(Math.random() * 5)];
  petkoMood.style.setProperty("--pwq-center-shift", `${centerShift}px`);
  petkoMoodImage.src = src;
  petkoMoodText.textContent = text;
  document.body.dataset.petkoMood = "true";
  petkoMood.hidden = false;
  petkoMood.classList.remove("showing");
  void petkoMood.offsetWidth;
  petkoMood.classList.add("showing");
  clearTimeout(petkoMoodTimer);
  petkoMoodTimer = setTimeout(() => {
    hidePetkoMood();
  }, visibleDuration);
}

function hidePetkoMood() {
  if (!petkoMood) return;
  clearTimeout(petkoMoodTimer);
  petkoMood.hidden = true;
  document.body.dataset.petkoMood = "false";
}

function maybeShowPetkoMood(mood, text, duration = 1600, options = {}) {
  const chance = options.chance ?? 0.35;
  const minGap = options.minGap ?? 9000;
  if (Math.random() > chance) return;
  showPetkoMood(mood, text, duration, { minGap, force: options.force });
}

function markQuietGuessForPetko() {
  petkoMoodQuietGuesses += 1;
  if (petkoMoodQuietGuesses >= 4) {
    petkoMoodQuietGuesses = 0;
    if (Math.random() <= 0.5) playPetkoMoment("quiet", { minGap: 10000 });
  }
}

function hidePetkoSplash() {
  if (petkoSplash) petkoSplash.hidden = true;
  showProfileHintOnce();
}

function fridayLabel() {
  return isPetkoFriday() ? "Petko Friday. " : "";
}

function recordFridayNormalWin() {
  if (!isPetkoFriday()) return "";
  const data = loadFridayBonus();
  data.normalStreak += 1;
  let text = `Petko Friday: Classic streak ${data.normalStreak}/5.`;
  if (data.normalStreak >= 5) {
    data.normalBonus += 5;
    data.normalStreak = 0;
    text = `Petko Friday: 5/5, +5 on the main score.`;
  }
  saveFridayBonus(data);
  renderNormalStats();
  updateScoreDisplay();
  return text;
}

function resetFridayNormalStreak() {
  if (!isPetkoFriday()) return;
  const data = loadFridayBonus();
  if (!data.normalStreak) return;
  data.normalStreak = 0;
  saveFridayBonus(data);
  renderNormalStats();
}

function recordFridayCompetitiveBonus(result) {
  if (!isPetkoFriday()) return;
  const data = loadFridayBonus();
  data.competitive[todayId()] = Math.max(0, Number(result.score) || 0);
  saveFridayBonus(data);
}

function emptyNormalChallengeBonus() {
  return { date: todayId(), streak: 0, bonus: 0 };
}

function loadNormalChallengeBonus() {
  try {
    const data = { ...emptyNormalChallengeBonus(), ...JSON.parse(localStorage.getItem(NORMAL_CHALLENGE_BONUS_KEY) || "{}") };
    if (data.date !== todayId()) return emptyNormalChallengeBonus();
    data.streak = Math.max(0, Number(data.streak) || 0);
    data.bonus = Math.max(0, Number(data.bonus) || 0);
    return data;
  } catch {
    return emptyNormalChallengeBonus();
  }
}

function saveNormalChallengeBonus(data) {
  localStorage.setItem(NORMAL_CHALLENGE_BONUS_KEY, JSON.stringify({ ...data, date: todayId() }));
}

function recordNormalChallengeWin() {
  const data = loadNormalChallengeBonus();
  data.streak += 1;
  let text = `Classic streak ${data.streak}/5 for an extra challenge.`;
  if (data.streak >= 5) {
    data.bonus += 1;
    data.streak = 0;
    text = "Classic streak 5/5: +1 allowed challenge.";
  }
  saveNormalChallengeBonus(data);
  updateChallengeQuota();
  renderNormalStats();
  return text;
}

function resetNormalChallengeStreak() {
  const data = loadNormalChallengeBonus();
  if (!data.streak) return;
  data.streak = 0;
  saveNormalChallengeBonus(data);
  renderNormalStats();
}

function emptyWeekendWitchChallengeBonus() {
  const weekendWindow = weekendWitchWindowContaining(new Date());
  return { weekend: weekendWitchId(), bonus: 0, lastAwardAt: weekendWindow?.start || Date.now() };
}

function loadWeekendWitchChallengeBonus() {
  try {
    const data = { ...emptyWeekendWitchChallengeBonus(), ...JSON.parse(localStorage.getItem(WEEKEND_WITCH_CHALLENGE_BONUS_KEY) || "{}") };
    if (data.weekend !== weekendWitchId()) return emptyWeekendWitchChallengeBonus();
    data.bonus = Math.max(0, Number(data.bonus) || 0);
    data.lastAwardAt = Math.max(0, Number(data.lastAwardAt) || Date.now());
    return data;
  } catch {
    return emptyWeekendWitchChallengeBonus();
  }
}

function saveWeekendWitchChallengeBonus(data) {
  localStorage.setItem(WEEKEND_WITCH_CHALLENGE_BONUS_KEY, JSON.stringify({ ...data, weekend: weekendWitchId() }));
}

function weekendWitchChallengeBonus() {
  if (!isWeekendWitchActive()) return 0;
  const data = loadWeekendWitchChallengeBonus();
  const elapsed = Math.max(0, Date.now() - data.lastAwardAt);
  const gained = Math.floor(elapsed / WEEKEND_WITCH_CHALLENGE_INTERVAL_MS);
  if (gained > 0) {
    data.bonus += gained;
    data.lastAwardAt += gained * WEEKEND_WITCH_CHALLENGE_INTERVAL_MS;
    saveWeekendWitchChallengeBonus(data);
  }
  return data.bonus;
}

function loadNormalStats() {
  try {
    return { started: 0, finished: 0, ...JSON.parse(localStorage.getItem(NORMAL_STATS_KEY) || "{}") };
  } catch {
    return { started: 0, finished: 0 };
  }
}

function saveNormalStats(stats) {
  localStorage.setItem(NORMAL_STATS_KEY, JSON.stringify(stats));
}

async function submitNormalStats(stats = loadNormalStats()) {
  if (!supabaseConfigured()) return false;
  const response = await fetch(supabaseUrl(`${normalStatsTable()}?on_conflict=device_id`), {
    method: "POST",
    headers: supabaseHeaders({ Prefer: "resolution=merge-duplicates,return=minimal" }),
    body: JSON.stringify({
      nickname: loadPlayerName() || "Player",
      device_id: deviceId(),
      started: Number(stats.started) || 0,
      finished: Number(stats.finished) || 0,
      updated_at: new Date().toISOString()
    })
  });
  return response.ok;
}

function displayNormalStats() {
  const local = loadNormalStats();
  if (!onlineNormalStatsSummary) return local;
  return {
    started: Math.max(Number(local.started) || 0, Number(onlineNormalStatsSummary.started) || 0),
    finished: Math.max(Number(local.finished) || 0, Number(onlineNormalStatsSummary.finished) || 0)
  };
}

async function refreshOnlineNormalStats() {
  if (!supabaseConfigured()) return;
  const name = loadPlayerName();
  if (!name) return;
  const rows = await fetchNormalStatsRows();
  const aggregated = normalSuccessRows(rows);
  const mine = aggregated.find((row) => sameChallengeName(row.nickname, name));
  onlineNormalStatsSummary = mine
    ? { started: Number(mine.started) || 0, finished: Number(mine.finished) || 0 }
    : null;
  renderNormalStats();
}

function loadSeenUnlockedAvatars() {
  try {
    return new Set(JSON.parse(localStorage.getItem(PROFILE_UNLOCK_SEEN_KEY) || "[]"));
  } catch {
    return new Set();
  }
}

function saveSeenUnlockedAvatars(ids = []) {
  localStorage.setItem(PROFILE_UNLOCK_SEEN_KEY, JSON.stringify([...new Set(ids)]));
}

async function refreshAvatarAchievements(options = {}) {
  const name = loadPlayerName();
  const stats = emptyAvatarAchievementStats();
  if (supabaseConfigured() && name) {
    const [normalRows, scoreRows, challengeRows] = await Promise.all([
      fetchNormalStatsRows().catch(() => []),
      fetchOnlineLeaderboard().catch(() => []),
      fetchChallengeStatsRows().catch(() => [])
    ]);
    const normalMine = normalSuccessRows(normalRows).find((row) => sameChallengeName(row.nickname, name));
    const tournamentMine = aggregateLeaderboard(scoreRows).find((row) => sameChallengeName(row.nickname, name));
    const challengeMine = normalizeChallengeWinStatsRows(challengeRows).find((row) => sameChallengeName(row.nickname, name));
    if (normalMine) {
      stats.normalStarted = Math.max(stats.normalStarted, Number(normalMine.started) || 0);
    }
    if (tournamentMine) {
      stats.tournaments = Math.max(stats.tournaments, Number(tournamentMine.playedDays || tournamentMine.attempts) || 0);
      stats.bestStreak = Math.max(stats.bestStreak, Number(tournamentMine.streak) || 0);
    }
    if (challengeMine) {
      stats.challengeWins = Math.max(stats.challengeWins, Number(challengeMine.wins) || 0);
    }
  }

  const previousUnlocked = new Set(unlockedProfileAvatars(avatarAchievementStats).map((avatar) => avatar.id));
  avatarAchievementStats = stats;
  const unlocked = unlockedProfileAvatars(stats);
  const seen = loadSeenUnlockedAvatars();
  const newlyUnlocked = unlocked.filter((avatar) => (
    avatar.unlockGroup &&
    avatar.unlockGroup !== "weekendWitch" &&
    !seen.has(avatar.id) &&
    !previousUnlocked.has(avatar.id)
  ));
  saveSeenUnlockedAvatars([
    ...seen,
    ...unlocked
      .filter((avatar) => avatar.unlockGroup && avatar.unlockGroup !== "weekendWitch")
      .map((avatar) => avatar.id)
  ]);
  if (profileModal && !profileModal.hidden) renderProfileModal();
  if (options.popup && newlyUnlocked.length) showAvatarUnlockPopup(newlyUnlocked);
}

function showAvatarUnlockPopup(avatars = []) {
  if (!avatars.length) return;
  const overlay = document.createElement("div");
  overlay.className = "avatar-unlock-modal";
  const card = document.createElement("article");
  card.className = "avatar-unlock-card";
  const title = document.createElement("h2");
  title.textContent = "New avatars unlocked";
  const text = document.createElement("p");
  text.textContent = "Choose a new sticker by clicking it.";
  const grid = document.createElement("div");
  grid.className = "avatar-unlock-grid";
  avatars.forEach((avatar) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "profile-avatar-option";
    if (avatar.src) {
      const image = document.createElement("img");
      image.src = avatar.src;
      image.alt = avatar.label;
      image.loading = "lazy";
      image.addEventListener("error", () => {
        image.remove();
        button.append(document.createTextNode(avatar.label));
      }, { once: true });
      button.append(image);
    } else {
      button.textContent = avatar.label;
    }
    button.addEventListener("click", () => {
      saveProfileAvatar(avatar.id);
      overlay.remove();
    });
    grid.append(button);
  });
  const close = document.createElement("button");
  close.type = "button";
  close.className = "avatar-unlock-close";
  close.textContent = "Later";
  close.addEventListener("click", () => overlay.remove());
  card.append(title, text, grid, close);
  overlay.append(card);
  document.body.append(overlay);
}

