  const title = document.createElement("h2");
  title.textContent = "Witch Hunt Weekend";
  const text = document.createElement("p");
  text.textContent = "It can begin. Choose a weekend avatar.";
  const grid = document.createElement("div");
  grid.className = "avatar-unlock-grid";
  avatars.forEach((avatar) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "profile-avatar-option";
    if (avatar.src) {
      const image = document.createElement("img");
      image.src = avatar.src;
      image.alt = avatar.label;
      image.loading = "lazy";
      image.addEventListener("error", () => {
        image.remove();
        button.append(document.createTextNode(avatar.label));
      }, { once: true });
      button.append(image);
    } else {
      button.textContent = avatar.label;
    }
    button.addEventListener("click", () => {
      saveProfileAvatar(avatar.id);
      overlay.remove();
    });
    grid.append(button);
  });
  const close = document.createElement("button");
  close.type = "button";
